type (
	hooks struct {
		Access, Archived, Audit, Checkpoint, Holder, Issue, IssueEvent, Outbox,
		Override, Owed, RowSeal, Tenant []ent.Hook
	}
	inters struct {
		Access, Archived, Audit, Checkpoint, Holder, Issue, IssueEvent, Outbox,
		Override, Owed, RowSeal, Tenant []ent.Interceptor
	}
)
